244	function CmvConfiguratorInner() {
245	  const navigate = useNavigate();
246	  const [searchParams] = useSearchParams();
247	  const cmvIdParam = searchParams.get('focus');
248	  const cmvId = cmvIdParam !== null && cmvIdParam !== '' ? parseInt(cmvIdParam, 10) : null;
249	
250	  const {
251	    loading,
252	    cmv,
253	    fichaData,
254	    items,
255	    insumos,
256	    positions,
257	    savePosition,
258	    refetch,
259	  } = useCmvGraph(cmvId);
260	
261	  const { fitView } = useReactFlow();
262	  const queryClient = useQueryClient();
263	  const [nodes, setNodes, onNodesChange] = useNodesState([]);
264	  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
265	
266	  // Detail panel state
267	  const [selectedItemData, setSelectedItemData] = useState<RawCmvItem | null>(null);
268	  const [editQty, setEditQty] = useState('');
269	  const [editUnit, setEditUnit] = useState('');
270	  const [editPreco, setEditPreco] = useState('');
271	  const [editObs, setEditObs] = useState('');
272	  const [isSaving, setIsSaving] = useState(false);
273	  const [isDeleting, setIsDeleting] = useState(false);
274	
275	  // Add item dialog state
276	  const [isAddOpen, setIsAddOpen] = useState(false);
277	  const [newTipo, setNewTipo] = useState<TipoItem>('embalagem');
278	  const [newInsumoId, setNewInsumoId] = useState<string>('');
279	  const [newQty, setNewQty] = useState('1');
280	  const [newUnit, setNewUnit] = useState('un');
281	  const [newPreco, setNewPreco] = useState('');
282	  const [newObs, setNewObs] = useState('');
283	  const [isAddSaving, setIsAddSaving] = useState(false);
284	
285	  // -------------------------------------------------------------------------
286	  // Build ReactFlow nodes/edges from hook data
287	  // -------------------------------------------------------------------------
288	  const buildGraph = useCallback(() => {
289	    if (!cmv) return;
290	
291	    const newNodes: Node[] = [];
292	    const newEdges: Edge[] = [];
293	
294	    const rootId = cmvNodeId(cmv.id);
295	
296	    // Root node
297	    newNodes.push({
298	      id: rootId,
299	      type: 'cmv',
300	      data: { nome: cmv.nome, custo: cmv.custo_calculado, status: cmv.status, kind: 'cmv' } as Record<string, unknown>,
301	      position: positions.get(rootId) ?? { x: 800, y: 300 },
302	    });
303	
304	    // Ficha base node
305	    if (fichaData) {
306	      const fId = fichaNodeId(fichaData.id);
307	      const rendQty = fichaData.rendimento_quantidade || 1;
308	      const custoUnitario = (fichaData.custo_calculado ?? 0) / rendQty;
309	
310	      newNodes.push({
311	        id: fId,
312	        type: 'ficha',
313	        data: {
314	          nome: fichaData.nome,
315	          custoUnitario,
316	          rendimento: `${fichaData.rendimento_quantidade} ${fichaData.rendimento_unidade}`,
317	          status: fichaData.status,
318	          kind: 'ficha',
319	        } as Record<string, unknown>,
320	        position: positions.get(fId) ?? { x: 400, y: 300 },
321	      });
322	
323	      newEdges.push({
324	        id: `e-${fId}-${rootId}`,
325	        source: fId,
326	        target: rootId,
327	        animated: true,
328	        style: { stroke: '#F59E0B', strokeWidth: 3 },
329	      });
330	    }
331	
332	    // Item nodes
333	    const addedInsumoIds = new Set<number>();
334	
335	    items.forEach((item, idx) => {
336	      const itemId = `item_${item.id}`;
337	      const label = item.insumo?.nome ?? item.observacao ?? `Item ${idx + 1}`;
338	
339	      newNodes.push({
340	        id: itemId,
341	        type: 'cmvItem',
342	        data: {
343	          tipo: item.tipo as TipoItem,
344	          quantidade: item.quantidade,
345	          unidade: item.unidade,
346	          custo: item.custo_calculado,
347	          label,
348	          kind: 'cmvItem',
349	          _rawItemId: item.id,
350	        } as Record<string, unknown>,
351	        position: positions.get(itemId) ?? { x: 400, y: 100 + idx * 160 },
352	      });
353	
354	      newEdges.push({
355	        id: `e-${itemId}-${rootId}`,
356	        source: itemId,
357	        target: rootId,
358	        style: { stroke: '#52525b', strokeWidth: 2 },
359	      });
360	
361	      // Insumo linked to item
362	      if (item.insumo_id && !addedInsumoIds.has(item.insumo_id)) {
363	        addedInsumoIds.add(item.insumo_id);
364	        const insId = insumoNodeId(item.insumo_id);
365	        const insData = insumos.find((i) => i.id === item.insumo_id);
366	
367	        newNodes.push({
368	          id: insId,
369	          type: 'insumo',
370	          data: {
371	            nome: insData?.nome ?? 'Insumo',
372	            preco: insData?.preco_custo ?? null,
373	            unidade: insData?.unidade_compra ?? 'un',
374	            kind: 'insumo',
375	          } as Record<string, unknown>,
376	          position: positions.get(insId) ?? { x: 100, y: 100 + idx * 160 },
377	        });
378	
379	        newEdges.push({
380	          id: `e-${insId}-${itemId}`,
381	          source: insId,
382	          target: itemId,
383	          style: { stroke: '#7c3aed', strokeWidth: 1.5 },
384	        });
385	      }
386	    });
387	
388	    // Apply dagre layout for nodes without saved positions
389	    const hasAllPositions = newNodes.every((n) => positions.has(n.id));
390	    if (!hasAllPositions && newNodes.length > 0) {
391	      const laid = layoutGraph(newNodes, newEdges, 'LR');
392	      setNodes(laid);
393	    } else {
394	      setNodes(newNodes);
395	    }
396	    setEdges(newEdges);
397	
398	    setTimeout(() => {
399	      fitView({ padding: 0.12, duration: 400 });
400	    }, 80);
401	  }, [cmv, fichaData, items, insumos, positions, fitView, setNodes, setEdges]);
402	
403	  useEffect(() => {
404	    if (!loading) {
405	      buildGraph();
406	    }
407	  }, [loading, buildGraph]);
408	
409	  // -------------------------------------------------------------------------
410	  // Node drag → save position
411	  // -------------------------------------------------------------------------
412	  const handleNodeDragStop: NodeDragHandler = useCallback(
413	    (_evt, node) => {
414	      savePosition(node.id, node.position.x, node.position.y);
415	    },
416	    [savePosition],
417	  );
418	
419	  // -------------------------------------------------------------------------
420	  // Node click → open detail panel
421	  // -------------------------------------------------------------------------
422	  const handleNodeClick = useCallback(
423	    (_evt: React.MouseEvent, node: Node) => {
424	      const rawId = (node.data as Record<string, unknown>)._rawItemId;
425	      if (typeof rawId !== 'number') {
426	        setSelectedItemData(null);
427	        return;
428	      }
429	      const found = items.find((it) => it.id === rawId);
430	      if (found) {
431	        setSelectedItemData(found);
432	        setEditQty(String(found.quantidade));
433	        setEditUnit(found.unidade);
434	        setEditPreco(found.preco_unitario_esboco !== null ? String(found.preco_unitario_esboco) : '');
435	        setEditObs(found.observacao ?? '');
436	      }
437	    },
438	    [items],
439	  );
440	
441	  // -------------------------------------------------------------------------
442	  // Auto-layout
443	  // -------------------------------------------------------------------------
444	  const handleAutoLayout = useCallback(() => {
445	    setNodes((prev) => {
446	      const laid = layoutGraph(prev, edges, 'LR');
447	      laid.forEach((n) => savePosition(n.id, n.position.x, n.position.y));
448	      return laid;
449	    });
450	    setTimeout(() => fitView({ padding: 0.12, duration: 400 }), 80);
451	  }, [edges, fitView, savePosition, setNodes]);
452	
453	  // -------------------------------------------------------------------------
454	  // Save item
455	  // -------------------------------------------------------------------------
456	  const handleSaveItem = useCallback(async () => {
457	    if (!selectedItemData) return;
458	    setIsSaving(true);
459	
460	    const updatePayload: Record<string, unknown> = {
461	      quantidade: parseFloat(editQty) || selectedItemData.quantidade,
462	      unidade: editUnit,
463	    };
464	    if (selectedItemData.tipo === 'outro') {
465	      updatePayload.preco_unitario_esboco = editPreco !== '' ? parseFloat(editPreco) : null;
466	      updatePayload.observacao = editObs.trim() || null;
467	    }
468	
469	    const { error } = await supabase
470	      .from('cmv_itens')
471	      .update(updatePayload)
472	      .eq('id', selectedItemData.id);
473	
474	    if (error) {
475	      toast.error(`Erro ao salvar: ${error.message}`);
476	    } else {
477	      toast.success('Item atualizado!');
478	      setSelectedItemData(null);
479	      await refetch();
480	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
481	    }
482	    setIsSaving(false);
483	  }, [selectedItemData, editQty, editUnit, editPreco, editObs, refetch, queryClient]);
484	
485	  // -------------------------------------------------------------------------
486	  // Delete item
487	  // -------------------------------------------------------------------------
488	  const handleDeleteItem = useCallback(async () => {
489	    if (!selectedItemData) return;
490	    setIsDeleting(true);
491	    const { error } = await supabase
492	      .from('cmv_itens')
493	      .delete()
494	      .eq('id', selectedItemData.id);
495	
496	    if (error) {
497	      toast.error(`Erro ao excluir: ${error.message}`);
498	    } else {
499	      toast.success('Item removido!');
500	      setSelectedItemData(null);
501	      await refetch();
502	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
503	    }
504	    setIsDeleting(false);
505	  }, [selectedItemData, refetch, queryClient]);
506	
507	  // -------------------------------------------------------------------------
508	  // Add item
509	  // -------------------------------------------------------------------------
510	  const handleAddItem = useCallback(async () => {
511	    if (!cmvId) return;
512	
513	    if (newTipo === 'embalagem' && !newInsumoId) {
514	      toast.error('Selecione um insumo para o item de embalagem.');
515	      return;
516	    }
517	    if (newTipo === 'outro' && newObs.trim() === '') {
518	      toast.error('Informe o nome do custo avulso no campo Observação.');
519	      return;
520	    }
521	
522	    setIsAddSaving(true);
523	
524	    const payload: Record<string, unknown> = {
525	      cmv_id: cmvId,
526	      tipo: newTipo,
527	      quantidade: parseFloat(newQty) || 1,
528	      unidade: newUnit,
529	      ordem: items.length,
530	    };
531	
532	    if (newTipo === 'embalagem') {
533	      payload.insumo_id = parseInt(newInsumoId, 10);
534	    } else {
535	      // outro: custo avulso
536	      payload.observacao = newObs.trim();
537	      payload.preco_unitario_esboco = newPreco !== '' ? parseFloat(newPreco) : null;
538	    }
539	
540	    const { error } = await supabase.from('cmv_itens').insert(payload);
541	
542	    if (error) {
543	      toast.error(`Erro ao criar item: ${error.message}`);
544	    } else {
545	      toast.success('Item adicionado!');
546	      setIsAddOpen(false);
547	      setNewTipo('embalagem');
548	      setNewInsumoId('');
549	      setNewQty('1');
550	      setNewUnit('un');
551	      setNewPreco('');
552	      setNewObs('');
553	      await refetch();
554	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
555	    }
556	    setIsAddSaving(false);
557	  }, [cmvId, newTipo, newInsumoId, newQty, newUnit, newPreco, newObs, items.length, refetch, queryClient]);
558	
559	  // -------------------------------------------------------------------------
560	  // Empty/loading states
561	  // -------------------------------------------------------------------------
562	  if (!cmvId) {
563	    return (
564	      <div className="h-[100dvh] bg-[#0F1117] flex flex-col items-center justify-center text-zinc-400">
565	        <Calculator className="h-12 w-12 mb-4 text-[#57715B]" />
566	        <p className="text-sm mb-4">Nenhum CMV selecionado</p>
567	        <Button variant="outline" onClick={() => navigate('/financeiro/cmv')}>
568	          <ArrowLeft className="mr-2 h-4 w-4" />
569	          Voltar ao CMV
570	        </Button>
571	      </div>
572	    );
573	  }
574	
575	  if (loading) {
